<?php
session_start(); require_once 'database.php';
if(!isset($_SESSION['loggedinEmail'])){header('Location: login.php');exit;} if(($_SESSION['userRole']??'')!=='admin'){header('Location: dashboard.php');exit;}
$errors=[];$success='';$title='';$company='';$location='';$jobType='';$description='';
if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['title']??'');$company=trim($_POST['company']??'');$location=trim($_POST['location']??'');$jobType=trim($_POST['job_type']??'');$description=trim($_POST['description']??'');foreach(['title'=>$title,'company'=>$company,'location'=>$location,'job_type'=>$jobType,'description'=>$description]as$field=>$value){if($value==='')$errors[$field]='This field is required.';}if(!$errors){$post=$conn->prepare('INSERT INTO jobs (title,company,location,job_type,description,created_by) VALUES (?,?,?,?,?,?)');$post->bind_param('sssssi',$title,$company,$location,$jobType,$description,$_SESSION['userId']);if($post->execute()){$success='Job posted successfully. It is now visible to job seekers.';$title=$company=$location=$jobType=$description='';}}}
$myJobs=$conn->prepare('SELECT id,title,company,location,job_type,description,created_at FROM jobs WHERE created_by=? ORDER BY created_at DESC');$myJobs->bind_param('i',$_SESSION['userId']);$myJobs->execute();$myJobs=$myJobs->get_result();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard | VUKA</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&display=swap" rel="stylesheet"><style>body{font-family:Inter,sans-serif;background:#fff5f0;color:#171615}.brand{font-weight:900;letter-spacing:-.08em;color:#171615;text-decoration:none;font-size:1.7rem}.card{border:0;border-radius:1rem;box-shadow:0 8px 24px #0000000d}.btn-vuka{background:#ff6b00;border:0;color:#171615;font-weight:800}.btn-vuka:hover{background:#e85f00}.job-detail-card{display:block;width:100%;text-align:left;background:#fff;border:1px solid #e1e1e1;border-radius:.75rem;padding:1rem;margin-top:.75rem;transition:.2s}.job-detail-card:hover{border-color:#146cff;box-shadow:0 0 0 3px #146cff1c}.job-detail-card small{color:#666}.modal-backdrop{display:none;position:fixed;inset:0;z-index:20;background:#0008;align-items:center;justify-content:center;padding:1rem}.modal-backdrop.open{display:flex}.job-modal{background:#fff;border-radius:1rem;width:min(620px,100%);max-height:90vh;overflow:auto;box-shadow:0 20px 55px #0005;padding:2rem;position:relative}.modal-cancel{position:absolute;top:1rem;left:1rem;border:0;background:#f3f3f3;border-radius:50%;width:34px;height:34px;font-size:1.25rem}.modal-label{font-size:.75rem;color:#ff6b00;font-weight:800;text-transform:uppercase;letter-spacing:.06em}</style></head><body><header class="bg-white border-bottom"><div class="container py-3 d-flex align-items-center"><a class="brand" href="index.php">VUKA</a><span class="ms-3 small fw-bold">Admin dashboard</span><a class="ms-auto btn btn-sm btn-outline-dark rounded-pill" href="logout.php">Log out</a></div></header><main class="container py-5"><div class="row g-4"><section class="col-lg-7"><div class="card p-4"><h1 class="h3 fw-bold">Post a new job</h1><p class="text-secondary">This job will appear automatically on the user dashboard.</p><?php if($success):?><div class="alert alert-success"><?php echo $success;?></div><?php endif;?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label fw-semibold">Job title</label><input class="form-control" name="title" value="<?php echo htmlspecialchars($title);?>"><?php if(isset($errors['title'])):?><small class="text-danger"><?php echo $errors['title'];?></small><?php endif;?></div><div class="col-md-6"><label class="form-label fw-semibold">Company</label><input class="form-control" name="company" value="<?php echo htmlspecialchars($company);?>"><?php if(isset($errors['company'])):?><small class="text-danger"><?php echo $errors['company'];?></small><?php endif;?></div><div class="col-md-6"><label class="form-label fw-semibold">Location</label><input class="form-control" name="location" placeholder="e.g. Lagos, Nigeria" value="<?php echo htmlspecialchars($location);?>"><?php if(isset($errors['location'])):?><small class="text-danger"><?php echo $errors['location'];?></small><?php endif;?></div><div class="col-md-6"><label class="form-label fw-semibold">Job type</label><select class="form-select" name="job_type"><option value="">Choose type</option><?php foreach(['Full-time','Part-time','Contract','Remote','Internship']as$type):?><option <?php echo $jobType===$type?'selected':'';?>><?php echo $type;?></option><?php endforeach;?></select><?php if(isset($errors['job_type'])):?><small class="text-danger"><?php echo $errors['job_type'];?></small><?php endif;?></div><div class="col-12"><label class="form-label fw-semibold">Job description</label><textarea class="form-control" rows="5" name="description"><?php echo htmlspecialchars($description);?></textarea><?php if(isset($errors['description'])):?><small class="text-danger"><?php echo $errors['description'];?></small><?php endif;?></div><div class="col-12"><button class="btn btn-vuka px-4" type="submit">Post job</button></div></div></form></div></section><aside class="col-lg-5"><div class="card p-4"><h2 class="h5 fw-bold">Your posted jobs</h2><p class="small text-secondary">Click a job card to view all details.</p><?php if($myJobs->num_rows):?><?php while($job=$myJobs->fetch_assoc()):?><button class="job-detail-card" type="button" data-title="<?php echo htmlspecialchars($job['title'],ENT_QUOTES);?>" data-company="<?php echo htmlspecialchars($job['company'],ENT_QUOTES);?>" data-location="<?php echo htmlspecialchars($job['location'],ENT_QUOTES);?>" data-type="<?php echo htmlspecialchars($job['job_type'],ENT_QUOTES);?>" data-description="<?php echo htmlspecialchars($job['description'],ENT_QUOTES);?>" data-date="<?php echo date('j F Y, g:i a',strtotime($job['created_at']));?>"><b><?php echo htmlspecialchars($job['title']);?></b><br><small><?php echo htmlspecialchars($job['company']);?> · <?php echo date('j M Y',strtotime($job['created_at']));?></small></button><?php endwhile;?><?php else:?><p class="text-secondary small mb-0">Your posted jobs will appear here.</p><?php endif;?></div></aside></div></main><div class="modal-backdrop" id="jobModal" role="dialog" aria-modal="true"><section class="job-modal"><button class="modal-cancel" type="button" onclick="closeModal()" aria-label="Close">×</button><div class="pt-3"><span class="modal-label" id="modalType"></span><h2 class="h3 fw-bold mt-2" id="modalTitle"></h2><p class="fw-semibold mb-1" id="modalCompany"></p><p class="text-secondary" id="modalLocation"></p><hr><h3 class="h6 fw-bold">Job description</h3><p class="text-secondary" style="white-space:pre-line" id="modalDescription"></p><small class="text-secondary" id="modalDate"></small></div></section></div><script>const modal=document.getElementById('jobModal');function closeModal(){modal.classList.remove('open')}document.querySelectorAll('.job-detail-card').forEach(card=>card.addEventListener('click',()=>{modalTitle.textContent=card.dataset.title;modalCompany.textContent=card.dataset.company;modalLocation.textContent=card.dataset.location;modalType.textContent=card.dataset.type;modalDescription.textContent=card.dataset.description;modalDate.textContent='Posted '+card.dataset.date;modal.classList.add('open')}));modal.addEventListener('click',event=>{if(event.target===modal)closeModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal()});</script></body></html>
